CREATE TABLE users (id UUID PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE job_applications (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,company VARCHAR(160) NOT NULL,position VARCHAR(180) NOT NULL,location VARCHAR(180),work_mode VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,priority VARCHAR(20) NOT NULL,source VARCHAR(80),job_url VARCHAR(1000),salary VARCHAR(120),recruiter_name VARCHAR(120),recruiter_email VARCHAR(190),applied_date DATE,deadline DATE,next_follow_up_date DATE,notes VARCHAR(5000),created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_job_user_status ON job_applications(user_id,status); CREATE INDEX idx_job_user_applied ON job_applications(user_id,applied_date);
